@contextmanager
def reraise(errors, into):
    """Reraises errors as other exception.

    When used as a context manager or decorator, passes the original exception
    to the 'into' callable if it's callable, allowing custom error handling.
    If 'into' is an exception class, raises it with the original as cause.
    """
    errors = _ensure_exceptable(errors)
    try:
        yield
    except errors as e:
        if callable(into):
            into(e)
        else:
            raise_from(into, e)


### api_call helper for common error handling pattern
def api_call(func, default=None):
    """Calls func within reraise(Exception, Exception). Returns result on success,
       or default if any exception occurs."""
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            if callable(default):
                return default(e)
            return default
    return wrapper

